function draftOf(words: number): string {
  const paragraphs: string[] = [];
  let count = 0;
  let index = 0;
  while (count < words) {
    paragraphs.push(`${PARAGRAPH} This is the ${index + 1}th visit I made.`);
    count += PARAGRAPH.split(/\s+/).length + 7;
    index += 1;
  }
  return paragraphs.join("\n\n");
}

